Tính số đo các góc trong tam giác ${PQR}$ biết $\widehat{P}: \widehat{Q}:\widehat{R}=31:79:70$. 
\choice
{ \True  $\widehat{P}= 31^{\circ}$ ,$\widehat{Q}= 79^{\circ}$, $\widehat{R}=70^{\circ} $   }
   {  $\widehat{P}= 32^{\circ}$ ,$\widehat{Q}= 79^{\circ}$, $\widehat{R}=69^{\circ} $   }
     {  $\widehat{P}= 32^{\circ}$ ,$\widehat{Q}= 78^{\circ}$, $\widehat{R}=70^{\circ} $  }
    {  $\widehat{P}= 31^{\circ}$ ,$\widehat{Q}= 80^{\circ}$, $\widehat{R}=69^{\circ} $  }
\loigiai{
Ta có $\dfrac{\widehat{P} }{31} = \dfrac{\widehat{Q} }{79}=\dfrac{\widehat{R} }{70}=\dfrac{\widehat{P}+\widehat{Q}+\widehat{R} }{180}=\dfrac{180^{\circ}}{180}=1^{\circ}$\\
Vậy $\widehat{P}= 31^{\circ}$ ,$\widehat{Q}= 79^{\circ}$, $\widehat{R}=70^{\circ} $
}\end{ex}
